/**
 * Creates a TTL-based cache wrapper for a function.
 * Results are stored with a timestamp and evicted after `ttlMs` milliseconds.
 *
 * @param {Function} fn - The function to wrap
 * @param {number} ttlMs - Time-to-live in milliseconds
 * @param {number} [maxSize=1000] - Maximum number of cached entries
 * @returns {Function} Wrapped function with cache
 */
function cache_with_ttl(fn, ttlMs, maxSize = 1000) {
  const cache = new Map();

  function evict() {
    const now = Date.now();
    for (const [key, entry] of cache) {
      if (now - entry.timestamp > ttlMs) {
        cache.delete(key);
      }
    }
  }

  const wrapped = function (...args) {
    const key = JSON.stringify(args);

    if (cache.has(key)) {
      const entry = cache.get(key);
      if (Date.now() - entry.timestamp <= ttlMs) {
        return entry.value;
      }
      cache.delete(key);
    }

    const result = fn(...args);

    if (cache.size >= maxSize) {
      evict();
      if (cache.size >= maxSize) {
        const oldest = cache.keys().next().value;
        cache.delete(oldest);
      }
    }

    cache.set(key, { value: result, timestamp: Date.now() });
    return result;
  };

  wrapped.cache = cache;
  wrapped.clear = () => cache.clear();
  wrapped.size = () => cache.size;

  return wrapped;
}

// ---------------------------------------------------------------------------
// Infix to Postfix (Shunting Yard Algorithm)
// ---------------------------------------------------------------------------

const PRECEDENCE = { '+': 1, '-': 1, '*': 2, '/': 2, '^': 3 };
const RIGHT_ASSOCIATIVE = new Set(['^']);

/**
 * Split an expression string into tokens (numbers, variables, operators, parens).
 * @param {string} expression
 * @returns {string[]}
 */
function tokenize(expression) {
  const tokens = [];
  let i = 0;
  while (i < expression.length) {
    const ch = expression[i];
    if (/\s/.test(ch)) {
      i++;
    } else if (/\d/.test(ch)) {
      let j = i;
      while (j < expression.length && /\d/.test(expression[j])) j++;
      tokens.push(expression.slice(i, j));
      i = j;
    } else if (/[a-zA-Z]/.test(ch)) {
      let j = i;
      while (j < expression.length && /[a-zA-Z0-9]/.test(expression[j])) j++;
      tokens.push(expression.slice(i, j));
      i = j;
    } else if ('+-*/^()'.includes(ch)) {
      tokens.push(ch);
      i++;
    } else {
      throw new Error(`Invalid character: "${ch}"`);
    }
  }
  return tokens;
}

/**
 * Return true if the token is an operand (number or variable name).
 * @param {string} token
 * @returns {boolean}
 */
function isOperand(token) {
  return /^[a-zA-Z0-9]+$/.test(token);
}

/**
 * Convert an infix expression to postfix (Reverse Polish) notation.
 *
 * Supports operators: +, -, *, /, ^ (exponentiation, right-associative)
 * Supports parentheses for grouping.
 * Operands can be single-letter variables or multi-digit numbers.
 *
 * @param {string} expression - A string infix expression, e.g. "A + B * C"
 * @returns {string} The equivalent postfix expression as a space-separated string.
 * @throws {Error} On mismatched parentheses or invalid tokens.
 */
function infix_to_postfix(expression) {
  if (typeof expression !== 'string') {
    throw new TypeError('Expression must be a string');
  }

  const output = [];
  const opStack = [];
  const tokens = tokenize(expression);

  for (const token of tokens) {
    if (isOperand(token)) {
      output.push(token);
    } else if (token === '(') {
      opStack.push(token);
    } else if (token === ')') {
      while (opStack.length > 0 && opStack[opStack.length - 1] !== '(') {
        output.push(opStack.pop());
      }
      if (opStack.length === 0) {
        throw new Error("Mismatched parentheses: unmatched ')'");
      }
      opStack.pop(); // discard '('
    } else if (token in PRECEDENCE) {
      while (
        opStack.length > 0 &&
        opStack[opStack.length - 1] !== '(' &&
        opStack[opStack.length - 1] in PRECEDENCE &&
        (
          PRECEDENCE[opStack[opStack.length - 1]] > PRECEDENCE[token] ||
          (
            PRECEDENCE[opStack[opStack.length - 1]] === PRECEDENCE[token] &&
            !RIGHT_ASSOCIATIVE.has(token)
          )
        )
      ) {
        output.push(opStack.pop());
      }
      opStack.push(token);
    } else {
      throw new Error(`Unknown token: "${token}"`);
    }
  }

  while (opStack.length > 0) {
    const top = opStack.pop();
    if (top === '(') {
      throw new Error("Mismatched parentheses: unmatched '('");
    }
    output.push(top);
  }

  return output.join(' ');
}

/**
 * Cached version of infix_to_postfix with TTL.
 * @param {string} expression
 * @param {number} [ttlMs=60000] - Cache TTL in milliseconds (default 60s)
 * @returns {string}
 */
const cachedInfixToPostfix = cache_with_ttl(infix_to_postfix, 60000);

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

function runTests() {
  let passed = 0;
  let failed = 0;

  function assert(cond, desc) {
    if (cond) { passed++; console.log(`  PASS  ${desc}`); }
    else { failed++; console.error(`  FAIL  ${desc}`); }
  }

  function assertThrows(fn, desc) {
    try { fn(); failed++; console.error(`  FAIL  ${desc} (no error thrown)`); }
    catch { passed++; console.log(`  PASS  ${desc}`); }
  }

  // ── Basic cases ───────────────────────────────────────────────────────

  console.log('\n=== Basic cases ===');
  assert(infix_to_postfix('A') === 'A', 'single operand: A');
  assert(infix_to_postfix('42') === '42', 'single number: 42');
  assert(infix_to_postfix('A + B') === 'A B +', 'simple addition: A + B');
  assert(infix_to_postfix('X - Y') === 'X Y -', 'simple subtraction: X - Y');
  assert(infix_to_postfix('A * B') === 'A B *', 'simple multiplication: A * B');
  assert(infix_to_postfix('A / B') === 'A B /', 'simple division: A / B');
  assert(infix_to_postfix('A ^ B') === 'A B ^', 'simple exponentiation: A ^ B');

  // ── Operator precedence ───────────────────────────────────────────────

  console.log('\n=== Operator precedence ===');
  assert(infix_to_postfix('A + B * C') === 'A B C * +', '* binds tighter than +: A + B * C');
  assert(infix_to_postfix('A * B + C') === 'A B * C +', '* evaluated first: A * B + C');
  assert(infix_to_postfix('A - B / C') === 'A B C / -', '/ binds tighter than -: A - B / C');
  assert(infix_to_postfix('A + B * C - D / E') === 'A B C * + D E / -', 'mixed + * - /');
  assert(infix_to_postfix('A * B ^ C') === 'A B C ^ *', '^ binds tighter than *: A * B ^ C');
  assert(infix_to_postfix('A + B ^ C * D') === 'A B C ^ D * +', '^ then * then +');

  // ── Associativity ─────────────────────────────────────────────────────

  console.log('\n=== Associativity ===');
  assert(infix_to_postfix('A ^ B ^ C') === 'A B C ^ ^', '^ is right-associative: A ^ B ^ C');
  assert(infix_to_postfix('A + B - C + D') === 'A B + C - D +', '+ - left-associative chain');
  assert(infix_to_postfix('A * B / C * D') === 'A B * C / D *', '* / left-associative chain');

  // ── Parentheses ───────────────────────────────────────────────────────

  console.log('\n=== Parentheses ===');
  assert(infix_to_postfix('(A + B) * C') === 'A B + C *', 'parens override precedence: (A+B)*C');
  assert(infix_to_postfix('((A + B) * (C - D))') === 'A B + C D - *', 'nested parens');
  assert(infix_to_postfix('(A + (B * (C ^ D)))') === 'A B C D ^ * +', 'deeply nested parens');
  assert(infix_to_postfix('(A)') === 'A', 'parens around single operand');
  assert(infix_to_postfix('A * (B + C)') === 'A B C + *', 'parens on right side');
  assert(infix_to_postfix('(A + B) * (C + D)') === 'A B + C D + *', 'parens on both sides');

  // ── Multi-character operands ──────────────────────────────────────────

  console.log('\n=== Multi-character operands ===');
  assert(infix_to_postfix('12 + 34') === '12 34 +', 'multi-digit numbers');
  assert(infix_to_postfix('abc + def') === 'abc def +', 'multi-char variables');
  assert(infix_to_postfix('x1 + y2') === 'x1 y2 +', 'alphanumeric variables');
  assert(infix_to_postfix('var1 * var2 + var3') === 'var1 var2 * var3 +', 'long variable names');

  // ── Complex expressions ───────────────────────────────────────────────

  console.log('\n=== Complex expressions ===');
  assert(
    infix_to_postfix('A + B * (C - D) / E ^ F') === 'A B C D - * E F ^ / +',
    'complex: A + B * (C - D) / E ^ F'
  );
  assert(
    infix_to_postfix('(A + B) * C - (D - E) * (F + G)') === 'A B + C * D E - F G + * -',
    'classic textbook example'
  );
  assert(
    infix_to_postfix('A * B + C / D - E ^ F') === 'A B * C D / + E F ^ -',
    'all four precedence levels'
  );
  assert(
    infix_to_postfix('((A + B) * C) ^ (D - E)') === 'A B + C * D E - ^',
    'parens with exponentiation'
  );

  // ── Whitespace variations ─────────────────────────────────────────────

  console.log('\n=== Whitespace variations ===');
  assert(infix_to_postfix('A+B*C') === 'A B C * +', 'no whitespace');
  assert(infix_to_postfix('  A   +  B  *  C  ') === 'A B C * +', 'extra whitespace');
  assert(infix_to_postfix('A\t+\tB') === 'A B +', 'tabs');

  // ── Edge cases ────────────────────────────────────────────────────────

  console.log('\n=== Edge cases ===');
  assert(infix_to_postfix('') === '', 'empty expression');
  assert(infix_to_postfix('   ') === '', 'whitespace-only expression');
  assert(infix_to_postfix('((((A))))') === 'A', 'redundant parens');

  // ── Error cases ───────────────────────────────────────────────────────

  console.log('\n=== Error handling ===');
  assertThrows(() => infix_to_postfix('A + B)'), 'unmatched close paren');
  assertThrows(() => infix_to_postfix('(A + B'), 'unmatched open paren');
  assertThrows(() => infix_to_postfix('A $ B'), 'invalid character');
  assertThrows(() => infix_to_postfix('((A + B)'), 'extra open paren');
  assertThrows(() => infix_to_postfix('A + B))'), 'extra close paren');
  assertThrows(() => infix_to_postfix(123), 'non-string input throws TypeError');
  assertThrows(() => infix_to_postfix(null), 'null input throws');

  // ── Numbers in complex expressions ────────────────────────────────────

  console.log('\n=== Numeric expressions ===');
  assert(infix_to_postfix('3 + 4 * 2') === '3 4 2 * +', '3 + 4 * 2');
  assert(infix_to_postfix('(1 + 2) * 3') === '1 2 + 3 *', '(1 + 2) * 3');
  assert(infix_to_postfix('100 / 25 + 7 * 2') === '100 25 / 7 2 * +', '100 / 25 + 7 * 2');
  assert(infix_to_postfix('2 ^ 10') === '2 10 ^', '2 ^ 10');

  // ── Cache TTL behavior ───────────────────────────────────────────────

  console.log('\n=== Cache TTL ===');
  const ttlFn = cache_with_ttl(infix_to_postfix, 100); // 100ms TTL

  const r1 = ttlFn('A + B * C');
  assert(r1 === 'A B C * +', 'first call returns correct value');
  assert(ttlFn.size() === 1, 'cache has 1 entry after first call');

  const r2 = ttlFn('A + B * C');
  assert(r2 === 'A B C * +', 'second call returns cached value');
  assert(ttlFn.size() === 1, 'cache still has 1 entry');

  ttlFn('X - Y');
  assert(ttlFn.size() === 2, 'cache has 2 entries for different inputs');

  // Wait for TTL to expire
  const start = Date.now();
  while (Date.now() - start < 150) { /* spin */ }

  const r3 = ttlFn('A + B * C');
  assert(r3 === 'A B C * +', 'value correct after TTL expiry');
  assert(ttlFn.size() >= 1, 'cache still functional after TTL');

  ttlFn.clear();
  assert(ttlFn.size() === 0, 'cache cleared successfully');

  // ── Cache key isolation ───────────────────────────────────────────────

  console.log('\n=== Cache key isolation ===');
  const c2 = cache_with_ttl((x) => x * 2, 5000);
  assert(c2(3) === 6, 'c2(3) = 6');
  assert(c2(5) === 10, 'c2(5) = 10');
  assert(c2(3) === 6, 'c2(3) cached = 6');
  assert(c2.size() === 2, 'two distinct cache keys');

  // ── Max size eviction ─────────────────────────────────────────────────

  console.log('\n=== Max size eviction ===');
  const c3 = cache_with_ttl((x) => x, 10000, 3);
  c3(1); c3(2); c3(3);
  assert(c3.size() === 3, 'cache at max size 3');
  c3(4);
  assert(c3.size() === 3, 'eviction keeps size at 3');

  // ── Cached infix_to_postfix ──────────────────────────────────────────

  console.log('\n=== Cached infix_to_postfix ===');
  cachedInfixToPostfix.clear();
  assert(cachedInfixToPostfix('(A + B) * C') === 'A B + C *', 'cached result correct');
  assert(cachedInfixToPostfix.size() === 1, 'cache populated');
  assert(cachedInfixToPostfix('(A + B) * C') === 'A B + C *', 'cache hit returns same result');
  assert(cachedInfixToPostfix.size() === 1, 'no duplicate entry on cache hit');

  // ── Summary ──────────────────────────────────────────────────────────

  console.log(`\n${'='.repeat(50)}`);
  console.log(`Results: ${passed} passed, ${failed} failed, ${passed + failed} total`);
  if (failed > 0) process.exit(1);
}

// Export for module use, run tests when executed directly
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { cache_with_ttl, infix_to_postfix, cachedInfixToPostfix, tokenize, isOperand };
  if (require.main === module) runTests();
} else {
  runTests();
}
